snippets.s4r:
s4r: {
  stage:4, sub:'おすすめ',
  main: () => ({ label:'このサイトで進む →', go:'s5' }),
  html: () => {
    const s = site();
    const others = Object.keys(SITES).filter(k => k !== S.site);
    return `
      <p class="kicker">サイト選び　結果</p>
      <div class="result">
        ${S.site === S.rec
          ? `<p class="label">あなたには</p><p class="answer" tabindex="-1" id="focusMe">${esc(s.name)}が<br>使いやすそうです</p>`
          : `<p class="label">あなたが選んだサイト</p><p class="answer" tabindex="-1" id="focusMe">${esc(s.name)}</p>`}
        <p style="margin:0">${esc(s.why)}</p>
      </div>
      <p class="small">「絶対にここが一番」というわけではありません。気になる場合は、ほかのサイトを選んでもかまいません。</p>
      <h2>ほかのサイト</h2>
      ${others.map(k => `
        <div class="card site">
          <div class="s-body"><span class="s-name">${esc(SITES[k].name)}</span><span class="s-why">${esc(SITES[k].why)}</span></div>
          <button class="mini-btn" type="button" data-site="${k}">こちらにする</button>
        </div>`).join('')}`;
  }
},
